DROP TABLE IF EXISTS data_kebun_tk CASCADE;

CREATE TABLE data_kebun_tk (
    id INT PRIMARY KEY,
    cro VARCHAR(50),
    region VARCHAR(100) NOT NULL,
    region_raw VARCHAR(100),
    nama_kebun VARCHAR(255) NOT NULL,
    name_tag VARCHAR(100),
    luasan NUMERIC(10, 2) DEFAULT 0,
    req_tk INT DEFAULT 0,
    tk_mei INT DEFAULT 0,
    tk_juni INT DEFAULT 0,
    target_juli INT DEFAULT 0,
    target_agustus INT DEFAULT 0,
    tk_juli INT DEFAULT 0,
    tk_agustus INT DEFAULT 0,
    updated_by VARCHAR(100) DEFAULT 'SYSTEM',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_data_kebun_tk_region ON data_kebun_tk(region);
CREATE INDEX idx_data_kebun_tk_cro ON data_kebun_tk(cro);
CREATE INDEX idx_data_kebun_tk_name_tag ON data_kebun_tk(name_tag);

ALTER TABLE data_kebun_tk ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public select on data_kebun_tk" ON data_kebun_tk FOR SELECT USING (true);
CREATE POLICY "Allow public insert on data_kebun_tk" ON data_kebun_tk FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow public update on data_kebun_tk" ON data_kebun_tk FOR UPDATE USING (true);

